-- Commercial notes and physical returns are separate from accounting corrections and settlement execution.
begin;
create table public.zp_credit_notes(
 id uuid primary key default gen_random_uuid(),org_id uuid not null,site_id uuid not null,sale_id uuid not null,member_id uuid not null,request_id uuid not null,
 payment_id uuid references public.zp_credit_payments(id),cash_id uuid,method text,amount_xaf bigint not null check(amount_xaf between 1 and 2147483647),
 reference text,reason text not null check(length(reason) between 5 and 500),created_at timestamptz not null default now(),
 unique(member_id,request_id),check((payment_id is null and cash_id is null and method is null and reference is null) or (payment_id is not null and cash_id is not null and method in ('cash','bank','mtn_momo','orange_money','card') and reference is not null and length(reference) between 4 and 160)),
 foreign key(sale_id,org_id,site_id) references public.zp_credit_sales(id,org_id,site_id),foreign key(cash_id,org_id,site_id) references public.zp_cash_sessions(id,org_id,site_id),foreign key(member_id,org_id) references public.zp_members(id,org_id));
create unique index zp_credit_refund_reference on public.zp_credit_notes(org_id,method,reference) where payment_id is not null;
create table public.zp_sale_returns(
 id uuid primary key default gen_random_uuid(),org_id uuid not null,site_id uuid not null,receipt_id uuid not null,item_id uuid not null,member_id uuid not null,request_id uuid not null,
 qty int not null check(qty>0),disposition text not null check(disposition in ('destroyed','quarantine','restock')),lot_id uuid,restock_milli bigint not null default 0 check(restock_milli>=0),restock_cost bigint not null default 0 check(restock_cost>=0),
 reason text not null check(length(reason) between 5 and 500),created_at timestamptz not null default now(),unique(member_id,request_id),
 check((disposition='restock' and lot_id is not null and restock_milli>0) or (disposition<>'restock' and lot_id is null and restock_milli=0 and restock_cost=0)),
 foreign key(receipt_id,org_id,site_id) references public.zp_cash_receipts(id,org_id,site_id),foreign key(item_id,org_id,site_id) references public.zp_menu_items(id,org_id,site_id),
 foreign key(lot_id,org_id,site_id) references public.zp_ingredient_lots(id,org_id,site_id),foreign key(member_id,org_id) references public.zp_members(id,org_id));
create or replace function public.zp_cash_expected(p_cash uuid) returns bigint language sql stable security invoker set search_path=pg_catalog,public as $$
 select c.opening_xaf+coalesce((select sum(amount_xaf) from public.zp_cash_receipts where cash_id=c.id and method='cash'),0)+coalesce((select sum(t.amount_xaf) from public.zp_cash_tenders t join public.zp_cash_receipts r on r.id=t.receipt_id where r.cash_id=c.id and t.method='cash'),0)+coalesce((select sum(p.amount_xaf) from public.zp_credit_payments p where p.cash_id=c.id and p.method='cash'),0)-coalesce((select sum(amount_xaf) from public.zp_cash_outflows where cash_id=c.id and method='cash'),0)+coalesce((select sum(case when direction='in' then amount_xaf else -amount_xaf end) from public.zp_treasury_reconciliation where cash_id=c.id),0)-coalesce((select sum(amount_xaf) from public.zp_credit_notes where cash_id=c.id and method='cash'),0) from public.zp_cash_sessions c where c.id=p_cash;
$$;
create function public.zp_credit_note_record(p_access text,p_site uuid,p_sale uuid,p_request uuid,p_payment uuid,p_cash uuid,p_amount bigint,p_reference text,p_reason text) returns uuid language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;s public.zp_credit_sales;x public.zp_credit_notes;pay public.zp_credit_payments;c public.zp_cash_sessions;i uuid;method_code text;ref text:=case when p_payment is null then null else trim(coalesce(p_reference,'')) end;why text:=trim(coalesce(p_reason,''));used bigint;begin
 m:=public.zp_erp_actor(p_access,p_site);if m.role_code<>'promoteur' then raise exception 'DENIED';end if;
 perform 1 from public.zp_site_modes where site_id=p_site for update;
 select * into x from public.zp_credit_notes where member_id=m.id and request_id=p_request;
 if x.id is not null then if (x.site_id,x.sale_id,x.payment_id,x.cash_id,x.amount_xaf,x.reference,x.reason) is distinct from (p_site,p_sale,p_payment,p_cash,p_amount,ref,why) then raise exception 'IDEMPOTENCY_CONFLICT';end if;return x.id;end if;
 select * into s from public.zp_credit_sales where id=p_sale and org_id=m.org_id and site_id=p_site for update;if s.id is null then raise exception 'DENIED';end if;
 if p_request is null or p_amount is null or p_amount not between 1 and 2147483647 or length(why) not between 5 and 500 or s.credit_note_xaf+p_amount>s.amount_xaf then raise exception 'INVALID_CREDIT_NOTE';end if;
 if p_payment is null then
  if p_cash is not null or p_reference is not null or p_amount>s.balance_xaf then raise exception 'CREDIT_NOTE_EXCEEDS_BALANCE';end if;
 else
  select * into pay from public.zp_credit_payments where id=p_payment and sale_id=s.id and org_id=m.org_id and site_id=p_site;if pay.id is null then raise exception 'DENIED';end if;
  select * into c from public.zp_cash_sessions where id=p_cash and org_id=m.org_id and site_id=p_site for update;if c.id is null then raise exception 'DENIED';end if;if c.closed_at is not null then raise exception 'CASH_CLOSED';end if;
  method_code:=pay.method;
  select coalesce(sum(amount_xaf),0) into used from public.zp_credit_notes where payment_id=pay.id;
  if p_amount>pay.amount_xaf-used or length(ref) not between 4 and 160 then raise exception 'REFUND_EXCEEDS_ORIGINAL_METHOD';end if;
  if method_code='cash' and p_amount>public.zp_cash_expected(c.id) then raise exception 'INSUFFICIENT_CASH_BALANCE';end if;
  if method_code<>'cash' then insert into public.zp_settlement_references values(m.org_id,method_code,ref);end if;
 end if;
 insert into public.zp_credit_notes(org_id,site_id,sale_id,member_id,request_id,payment_id,cash_id,method,amount_xaf,reference,reason) values(m.org_id,p_site,s.id,m.id,p_request,p_payment,p_cash,method_code,p_amount,ref,why) returning id into i;
 update public.zp_credit_sales set credit_note_xaf=credit_note_xaf+p_amount,refunded_xaf=refunded_xaf+case when p_payment is null then 0 else p_amount end where id=s.id;
 return i;end $$;
create function public.zp_sale_return_record(p_access text,p_site uuid,p_receipt uuid,p_item uuid,p_request uuid,p_qty int,p_disposition text,p_lot uuid,p_reason text) returns uuid language plpgsql security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;r public.zp_cash_receipts;x public.zp_sale_returns;line public.zp_order_lines;alloc public.zp_direct_sale_allocations;lot public.zp_ingredient_lots;rule public.zp_direct_sale_rules;used_qty bigint;used_milli bigint;used_cost bigint;q bigint:=0;cost bigint:=0;i uuid;why text:=trim(coalesce(p_reason,''));begin
 m:=public.zp_erp_actor(p_access,p_site);if m.role_code<>'promoteur' then raise exception 'DENIED';end if;
 perform 1 from public.zp_site_modes where site_id=p_site for update;
 select * into x from public.zp_sale_returns where member_id=m.id and request_id=p_request;
 if x.id is not null then if (x.site_id,x.receipt_id,x.item_id,x.qty,x.disposition,x.lot_id,x.reason) is distinct from (p_site,p_receipt,p_item,p_qty,p_disposition,p_lot,why) then raise exception 'IDEMPOTENCY_CONFLICT';end if;return x.id;end if;
 select * into r from public.zp_cash_receipts where id=p_receipt and org_id=m.org_id and site_id=p_site;if r.id is null then raise exception 'DENIED';end if;
 select * into line from public.zp_order_lines where order_id=r.order_id and item_id=p_item;
 select coalesce(sum(qty),0) into used_qty from public.zp_sale_returns where receipt_id=r.id and item_id=p_item;
 if p_request is null or line.item_id is null or p_qty is null or p_qty not between 1 and line.qty-used_qty or p_disposition is null or p_disposition not in ('destroyed','quarantine','restock') or length(why) not between 5 and 500 then raise exception 'INVALID_SALE_RETURN';end if;
 if p_disposition='restock' then
  select * into rule from public.zp_direct_sale_rules where item_id=p_item and org_id=m.org_id and site_id=p_site;
  select * into alloc from public.zp_direct_sale_allocations where receipt_id=r.id and item_id=p_item and lot_id=p_lot;
  select * into lot from public.zp_ingredient_lots where id=p_lot and org_id=m.org_id and site_id=p_site for update;
  if rule.item_id is null or alloc.lot_id is null or lot.id is null or lot.ingredient_id<>rule.ingredient_id or lot.expires_on<(now() at time zone 'Africa/Douala')::date or lot.usable_until<=now() then raise exception 'RETURN_RESTOCK_REQUIRES_TRACE';end if;
  q:=p_qty::bigint*rule.qty_milli;
  select coalesce(sum(restock_milli),0),coalesce(sum(restock_cost),0) into used_milli,used_cost from public.zp_sale_returns where receipt_id=r.id and item_id=p_item and lot_id=p_lot and disposition='restock';
  if q>alloc.qty_milli-used_milli then raise exception 'RETURN_RESTOCK_REQUIRES_TRACE';end if;
  cost:=floor(alloc.cost_xaf::numeric*(used_milli+q)/alloc.qty_milli)::bigint-used_cost;
  update public.zp_ingredient_lots set remaining_milli=remaining_milli+q,remaining_cost=remaining_cost+cost where id=lot.id;
  update public.zp_menu_items set available_qty=available_qty+p_qty where id=p_item;
 elsif p_lot is not null then raise exception 'INVALID_SALE_RETURN';end if;
 insert into public.zp_sale_returns(org_id,site_id,receipt_id,item_id,member_id,request_id,qty,disposition,lot_id,restock_milli,restock_cost,reason) values(m.org_id,p_site,r.id,p_item,m.id,p_request,p_qty,p_disposition,p_lot,q,cost,why) returning id into i;return i;end $$;
create view public.zp_commercial_note_view with (security_invoker=true) as
 select o.org_id,o.site_id,o.id,r.order_id,r.id receipt_id,'refund'::text as kind,o.amount_xaf,o.method,o.reference,o.reason,o.created_at from public.zp_cash_outflows o join public.zp_cash_receipts r on r.id=o.source_id where o.kind='refund'
 union all select n.org_id,n.site_id,n.id,s.order_id,s.receipt_id,case when n.payment_id is null then 'credit_note' else 'credit_refund' end,n.amount_xaf,n.method,n.reference,n.reason,n.created_at from public.zp_credit_notes n join public.zp_credit_sales s on s.id=n.sale_id;
revoke all on public.zp_commercial_note_view from public,anon,authenticated;grant select on public.zp_commercial_note_view to service_role;
create function public.zp_commercial_snapshot(p_access text,p_site uuid) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;begin m:=public.zp_erp_actor(p_access,p_site);if m.role_code<>'promoteur' then raise exception 'DENIED';end if;
 return jsonb_build_object('organization',(select name from public.zp_organizations where id=m.org_id),'site',(select name from public.zp_sites where id=p_site),
 'notes',coalesce((select jsonb_agg(to_jsonb(q) order by q.created_at desc) from (select n.id,n.order_id,n.receipt_id,n.kind,n.amount_xaf,n.method,n.reference,n.reason,n.created_at,o.service_number from public.zp_commercial_note_view n join public.zp_orders o on o.id=n.order_id where n.org_id=m.org_id and n.site_id=p_site order by n.created_at desc limit 300)q),'[]'::jsonb),
 'receipts',coalesce((select jsonb_agg(to_jsonb(q) order by q.created_at desc) from (select r.id,r.order_id,r.amount_xaf,r.method,r.created_at,o.service_number,(select coalesce(jsonb_agg(jsonb_build_object('item_id',l.item_id,'name',i.name,'qty',l.qty,'returned',coalesce((select sum(x.qty) from public.zp_sale_returns x where x.receipt_id=r.id and x.item_id=l.item_id),0),'lots',coalesce((select jsonb_agg(jsonb_build_object('id',a.lot_id,'label',g.lot_label,'qty_milli',a.qty_milli)) from public.zp_direct_sale_allocations a join public.zp_ingredient_lots g on g.id=a.lot_id where a.receipt_id=r.id and a.item_id=l.item_id),'[]'::jsonb))) ,'[]'::jsonb) from public.zp_order_lines l join public.zp_menu_items i on i.id=l.item_id where l.order_id=r.order_id) lines from public.zp_cash_receipts r join public.zp_orders o on o.id=r.order_id where r.org_id=m.org_id and r.site_id=p_site order by r.created_at desc limit 300)q),'[]'::jsonb),
 'returns',coalesce((select jsonb_agg(to_jsonb(q) order by q.created_at desc) from (select x.id,x.receipt_id,x.item_id,i.name,x.qty,x.disposition,x.lot_id,x.restock_cost,x.reason,x.created_at from public.zp_sale_returns x join public.zp_menu_items i on i.id=x.item_id where x.org_id=m.org_id and x.site_id=p_site order by x.created_at desc limit 300)q),'[]'::jsonb),
 'credit_sales',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'order_id',s.order_id,'amount_xaf',s.amount_xaf,'balance_xaf',s.balance_xaf,'credit_note_xaf',s.credit_note_xaf,'paid_xaf',s.paid_xaf,'refunded_xaf',s.refunded_xaf,'payments',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'method',p.method,'amount_xaf',p.amount_xaf,'refundable_xaf',p.amount_xaf-coalesce((select sum(n.amount_xaf) from public.zp_credit_notes n where n.payment_id=p.id),0))),'[]'::jsonb) from public.zp_credit_payments p where p.sale_id=s.id)) ) from public.zp_credit_sales s where s.org_id=m.org_id and s.site_id=p_site),'[]'::jsonb),
 'sessions',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'label',coalesce(d.label,'Caisse principale'),'expected_xaf',public.zp_cash_expected(c.id))) from public.zp_cash_sessions c left join public.zp_cash_desks d on d.id=c.desk_id where c.org_id=m.org_id and c.site_id=p_site and c.closed_at is null),'[]'::jsonb));end $$;
create or replace view public.zp_ledger_sources with (security_invoker=true) as
 select org_id,site_id,(case when method='credit' then 'credit_sale' else 'sale' end)::text as kind,id as source_id,(created_at at time zone 'Africa/Douala')::date as entry_date,amount_xaf,'Sale receipt'::text as label from public.zp_cash_receipts
 union all select r.org_id,r.site_id,'sale_cost',r.id,(r.created_at at time zone 'Africa/Douala')::date,sum(c.cost_xaf)::bigint,'Cost of sale' from public.zp_cash_receipts r join public.zp_sale_costs c on c.receipt_id=r.id group by r.id,r.org_id,r.site_id,r.created_at having count(*)=count(c.cost_xaf) and sum(c.cost_xaf)>0
 union all select org_id,site_id,'purchase_receipt',id,(created_at at time zone 'Africa/Douala')::date,cost_xaf,'Purchase receipt' from public.zp_purchase_receipts where cost_xaf>0
 union all select org_id,site_id,'supplier_payment',id,(created_at at time zone 'Africa/Douala')::date,amount_xaf,'Supplier payment' from public.zp_supplier_payments
 union all select org_id,site_id,'expense',id,expense_date,amount_xaf,label from public.zp_expenses
 union all select org_id,site_id,'inventory_loss',id,(created_at at time zone 'Africa/Douala')::date,loss_cost,reason from public.zp_inventory_counts where loss_cost>0
 union all select org_id,site_id,'deposit_'||direction,id,(created_at at time zone 'Africa/Douala')::date,amount_xaf,'Packaging deposit/refund' from public.zp_container_finance
 union all select org_id,site_id,'credit_payment',id,(created_at at time zone 'Africa/Douala')::date,amount_xaf,'Customer credit payment' from public.zp_credit_payments
 union all select org_id,site_id,'braise_loss',id,(created_at at time zone 'Africa/Douala')::date,loss_cost,'Prepared stock loss' from public.zp_braise_losses where loss_cost>0
 union all select org_id,destination_site,'transfer_loss',id,(received_at at time zone 'Africa/Douala')::date,transferred_cost-received_cost,'Material transfer loss' from public.zp_transfers where state='received' and transferred_cost>received_cost
 union all select org_id,destination_site,'prepared_transfer_loss',id,(received_at at time zone 'Africa/Douala')::date,transferred_cost-received_cost,'Preparation transfer loss' from public.zp_prepared_transfers where state='received' and transferred_cost>received_cost
 union all select org_id,site_id,kind,id,(created_at at time zone 'Africa/Douala')::date,amount_xaf,reason from public.zp_cash_outflows where kind in ('refund','withdrawal')
 union all select org_id,site_id,'prepared_expiry_loss',id,(created_at at time zone 'Africa/Douala')::date,loss_cost,reason from public.zp_expired_preparation_losses where loss_cost>0
 union all select org_id,site_id,'inventory_gain',id,(decided_at at time zone 'Africa/Douala')::date,approved_value,reason from public.zp_inventory_gains where state='approved' and approved_value>0
 union all select org_id,site_id,case when payment_id is null then 'credit_note' else 'credit_refund' end,id,(created_at at time zone 'Africa/Douala')::date,amount_xaf,reason from public.zp_credit_notes
 union all select org_id,site_id,'stock_return',id,(created_at at time zone 'Africa/Douala')::date,restock_cost,reason from public.zp_sale_returns where restock_cost>0;
create or replace function public.zp_erp_snapshot(p_access text,p_site uuid) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;ingredients jsonb;lots jsonb;batches jsonb;expenses jsonb;recipes jsonb;begin m:=public.zp_erp_actor(p_access,p_site);
 select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'name',i.name,'sku',i.sku,'unit',i.unit,'reorder_milli',i.reorder_milli,'supplier_whatsapp',i.supplier_whatsapp,'available_milli',coalesce((select sum(l.remaining_milli) from public.zp_ingredient_lots l where l.ingredient_id=i.id and (l.expires_on is null or l.expires_on>=(now() at time zone 'Africa/Douala')::date) and (l.usable_until is null or l.usable_until>now())),0)) order by i.name),'[]'::jsonb) into ingredients from public.zp_ingredients i where i.org_id=m.org_id and i.site_id=p_site;
 select coalesce(jsonb_agg(to_jsonb(l) order by l.received_at desc),'[]'::jsonb) into lots from (select id,ingredient_id,lot_label,supplier,remaining_milli,remaining_cost,expires_on,usable_until,received_at from public.zp_ingredient_lots where org_id=m.org_id and site_id=p_site order by received_at desc limit 200) l;
 select coalesce(jsonb_agg(to_jsonb(b) order by b.created_at desc),'[]'::jsonb) into batches from (select id,item_id,servings,cost_xaf,recipe_version_id,created_at from public.zp_production_batches where org_id=m.org_id and site_id=p_site order by created_at desc limit 100) b;
 select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at desc),'[]'::jsonb) into expenses from (select id,category,label,amount_xaf,method,reference,expense_date,created_at from public.zp_expenses where org_id=m.org_id and site_id=p_site order by created_at desc limit 100) e;
 select coalesce(jsonb_agg(to_jsonb(c)),'[]'::jsonb) into recipes from (select item_id,ingredient_id,qty_milli from public.zp_recipe_components where org_id=m.org_id and site_id=p_site) c;
 return jsonb_build_object('ingredients',ingredients,'lots',lots,'batches',batches,'expenses',expenses,'recipes',recipes,'conversions',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'ingredient_id',c.ingredient_id,'label',c.label,'base_milli_per_unit',c.base_milli_per_unit) order by c.label) from public.zp_unit_conversions c where c.org_id=m.org_id and c.site_id=p_site),'[]'::jsonb),'recipe_versions',coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'item_id',v.item_id,'version',v.version,'components',v.components,'reason',v.reason,'created_at',v.created_at) order by v.version desc) from public.zp_recipe_versions v where v.org_id=m.org_id and v.site_id=p_site),'[]'::jsonb),'recorded_expenses_xaf',(select coalesce(sum(amount_xaf),0) from public.zp_expenses where org_id=m.org_id and site_id=p_site),'recorded_receipts_xaf',(select coalesce(sum(amount_xaf),0) from public.zp_cash_receipts where org_id=m.org_id and site_id=p_site and method<>'credit')+(select coalesce(sum(amount_xaf),0) from public.zp_credit_payments where org_id=m.org_id and site_id=p_site),'credit_notes_xaf',(select coalesce(sum(amount_xaf),0) from public.zp_credit_notes where org_id=m.org_id and site_id=p_site and payment_id is null),'refunds_xaf',(select coalesce(sum(amount_xaf),0) from public.zp_cash_outflows where org_id=m.org_id and site_id=p_site and kind='refund')+(select coalesce(sum(amount_xaf),0) from public.zp_credit_notes where org_id=m.org_id and site_id=p_site and payment_id is not null),'recorded_sales_xaf',(select coalesce(sum(amount_xaf),0) from public.zp_cash_receipts where org_id=m.org_id and site_id=p_site),'recorded_cost_xaf',case when exists(select 1 from public.zp_cash_receipts r where r.org_id=m.org_id and r.site_id=p_site)
 and not exists(select 1 from public.zp_cash_receipts r join public.zp_order_lines l on l.order_id=r.order_id left join public.zp_sale_costs c on c.receipt_id=r.id and c.item_id=l.item_id where r.org_id=m.org_id and r.site_id=p_site and c.cost_xaf is null)
 then (select sum(cost_xaf) from public.zp_sale_costs where org_id=m.org_id and site_id=p_site) else null end,'accounting_status','mapping_required');end $$;
create or replace function public.zp_pilotage(p_access text,p_site uuid,p_start date,p_end date) returns jsonb language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare m public.zp_members;today date:=(now() at time zone 'Africa/Douala')::date;lo timestamptz;hi timestamptz;revenue bigint;cost bigint;unknown_count bigint;receipt_count bigint;history jsonb;first_day date;expense bigint;low_count bigint;late_count bigint;feedback_count bigint;feedback_avg numeric;variance bigint;post_metrics jsonb;begin
 m:=public.zp_erp_actor(p_access,p_site);
 if p_start is null or p_end is null or p_start>p_end or p_end>today or p_end-p_start>365 then raise exception 'INVALID_PERIOD';end if;
 lo:=p_start::timestamp at time zone 'Africa/Douala';hi:=(p_end+1)::timestamp at time zone 'Africa/Douala';
 select coalesce(sum(r.amount_xaf),0),count(*) into revenue,receipt_count from public.zp_cash_receipts r where r.org_id=m.org_id and r.site_id=p_site and r.created_at>=lo and r.created_at<hi;
 select count(*) into unknown_count from public.zp_cash_receipts r where r.org_id=m.org_id and r.site_id=p_site and r.created_at>=lo and r.created_at<hi and exists(select 1 from public.zp_order_lines l left join public.zp_sale_costs c on c.receipt_id=r.id and c.item_id=l.item_id where l.order_id=r.order_id and c.cost_xaf is null);
 if receipt_count>0 and unknown_count=0 then select coalesce(sum(c.cost_xaf),0) into cost from public.zp_sale_costs c join public.zp_cash_receipts r on r.id=c.receipt_id where r.org_id=m.org_id and r.site_id=p_site and r.created_at>=lo and r.created_at<hi;end if;
 select coalesce(sum(amount_xaf),0) into expense from public.zp_expenses where org_id=m.org_id and site_id=p_site and expense_date between p_start and p_end;
 select count(*) into low_count from public.zp_ingredients i where i.org_id=m.org_id and i.site_id=p_site and i.reorder_milli>=coalesce((select sum(l.remaining_milli) from public.zp_ingredient_lots l where l.ingredient_id=i.id and (l.expires_on is null or l.expires_on>=today) and (l.usable_until is null or l.usable_until>now())),0);
 select count(*) into late_count from public.zp_orders o where o.org_id=m.org_id and o.site_id=p_site and o.status not in ('served','cancelled') and o.guest_served_at is null and o.promised_at<now();
 select count(*),round(avg(rating),2) into feedback_count,feedback_avg from public.zp_feedback where org_id=m.org_id and site_id=p_site and created_at>=lo and created_at<hi;
 select coalesce(sum(abs(counted_xaf-expected_xaf)),0) into variance from public.zp_cash_sessions where org_id=m.org_id and site_id=p_site and closed_at>=lo and closed_at<hi;
 select min((created_at at time zone 'Africa/Douala')::date) into first_day from public.zp_cash_receipts where org_id=m.org_id and site_id=p_site;
 select coalesce(jsonb_agg(jsonb_build_object('day',x.receipt_day,'recorded_xaf',x.amount) order by x.receipt_day),'[]'::jsonb) into history from (select (created_at at time zone 'Africa/Douala')::date as receipt_day,sum(amount_xaf) as amount from public.zp_cash_receipts where org_id=m.org_id and site_id=p_site and created_at>=((today-28)::timestamp at time zone 'Africa/Douala') and created_at<(today::timestamp at time zone 'Africa/Douala') group by 1)x;
 select coalesce(jsonb_agg(to_jsonb(x) order by x.post),'[]'::jsonb) into post_metrics from (select l.post,sum(l.qty) portions,sum(l.line_total_xaf) recorded_xaf from public.zp_cash_receipts r join public.zp_order_lines l on l.order_id=r.order_id where r.org_id=m.org_id and r.site_id=p_site and r.created_at>=lo and r.created_at<hi group by l.post)x;
 return jsonb_build_object('start',p_start,'end',p_end,'as_of',now(),'today',today,'first_recorded_sale_day',first_day,'credit_notes_xaf',(select coalesce(sum(amount_xaf),0) from public.zp_credit_notes where org_id=m.org_id and site_id=p_site and payment_id is null and created_at>=lo and created_at<hi),'refunds_xaf',(select coalesce(sum(amount_xaf),0) from public.zp_cash_outflows where org_id=m.org_id and site_id=p_site and kind='refund' and created_at>=lo and created_at<hi)+(select coalesce(sum(amount_xaf),0) from public.zp_credit_notes where org_id=m.org_id and site_id=p_site and payment_id is not null and created_at>=lo and created_at<hi),'recorded_xaf',revenue,'collected_xaf',(select coalesce(sum(amount_xaf),0) from public.zp_cash_receipts where org_id=m.org_id and site_id=p_site and method<>'credit' and created_at>=lo and created_at<hi)+(select coalesce(sum(amount_xaf),0) from public.zp_credit_payments where org_id=m.org_id and site_id=p_site and created_at>=lo and created_at<hi),'receipts',receipt_count,'uncosted_receipts',unknown_count,'known_cost_xaf',cost,'gross_margin_xaf',case when cost is not null then revenue-cost else null end,'expenses_xaf',expense,'current_low_stock',low_count,'current_late_orders',late_count,'feedback_count',feedback_count,'feedback_average',feedback_avg,'absolute_cash_variance_xaf',variance,'history_28',history,'posts',post_metrics,'service_team',coalesce((select jsonb_agg(to_jsonb(v) order by v.member_id) from (select e.member_id,mem.login_id,count(distinct e.order_id) completed_orders,count(*) handed_lines from public.zp_order_events e join public.zp_orders o on o.id=e.order_id and o.org_id=e.org_id and o.site_id=e.site_id join public.zp_members mem on mem.id=e.member_id and mem.org_id=e.org_id where e.org_id=m.org_id and e.site_id=p_site and e.event_type='line_state' and e.payload->>'state'='served' and e.at>=lo and e.at<hi and o.status='served' group by e.member_id,mem.login_id)v),'[]'::jsonb));
end $$;
do $$ declare t text;f record;begin
 foreach t in array array['zp_credit_notes','zp_sale_returns'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select,insert on public.%I to service_role',t);end loop;
 for f in select p.oid::regprocedure sig from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('zp_credit_note_record','zp_sale_return_record','zp_commercial_snapshot') loop execute format('revoke all on function %s from public,anon,authenticated',f.sig);execute format('grant execute on function %s to service_role',f.sig);end loop;end $$;
commit;
